 def middleNode(self,head):
  slow=fast=head
  while fast and fast.next:slow=slow.next;fast=fast.next.next
  return slow

class Solution:
 def projectionArea(self,grid):
  if not grid:return 0
  top=sum(v>0 for row in grid for v in row);rows=sum(max(row) for row in grid);cols=sum(max(grid[r][c] for r in range(len(grid))) for c in range(len(grid[0])))
  return top+rows+cols

