class Solution:
 def fairCandySwap(self,aliceSizes,bobSizes):
  delta=(sum(aliceSizes)-sum(bobSizes))//2;b=set(bobSizes)
  for x in aliceSizes:
   if x-delta in b:return [x,x-delta]
  return []

